  VALUES (genesis_two,genesis_module,2,'Gênesis 2','O Deus que descansa, forma, planta, ordena, provê e estabelece a comunhão humana.',25)
  ON CONFLICT (module_id,chapter_number) DO UPDATE SET title=EXCLUDED.title, summary=EXCLUDED.summary, total_verses=EXCLUDED.total_verses;

