  VALUES
   ('b2000002-0000-4000-8000-000000000001',genesis_module,'genesis-2-1-3-descanso-de-deus','Gênesis 2:1–3 — O descanso de Deus','A conclusão da semana da criação apresenta a obra terminada, o descanso divino e a santificação do sétimo dia.',55,'free',9,true,'published','Gênesis 2:1-3',ARRAY['descanso','sétimo dia','santidade','criação'],genesis_two,1,3),
   ('b2000002-0000-4000-8000-000000000004',genesis_module,'genesis-2-4-7-homem-do-po','Gênesis 2:4–7 — O homem formado do pó','O relato focaliza a terra, a provisão de Deus e a formação do ser humano como criatura vivente diante do Criador.',58,'free',10,true,'published','Gênesis 2:4-7',ARRAY['adão','pó','fôlego de vida','terra','humanidade'],genesis_two,4,7),
   ('b2000002-0000-4000-8000-000000000008',genesis_module,'genesis-2-8-14-jardim-do-eden','Gênesis 2:8–14 — O jardim do Éden','Deus planta um jardim de provisão e vida, situando a humanidade num lugar real apresentado com geografia parcialmente não identificável.',58,'free',11,true,'published','Gênesis 2:8-14',ARRAY['Éden','jardim','árvore da vida','rios','provisão'],genesis_two,8,14),
   ('b2000002-0000-4000-8000-000000000015',genesis_module,'genesis-2-15-17-trabalho-e-mandamento','Gênesis 2:15–17 — Trabalho, limite e mandamento','O ser humano recebe uma vocação no jardim e um mandamento claro que une liberdade, limite, responsabilidade e consequência.',60,'free',12,true,'published','Gênesis 2:15-17',ARRAY['trabalho','guardar','mandamento','árvore','obediência'],genesis_two,15,17),
   ('b2000002-0000-4000-8000-000000000018',genesis_module,'genesis-2-18-20-nao-e-bom-so','Gênesis 2:18–20 — Não é bom que o homem esteja só','A primeira declaração de “não bom” conduz à procura de uma auxiliadora correspondente; os animais revelam a responsabilidade humana e a insuficiência de qualquer animal como par.',52,'free',13,true,'published','Gênesis 2:18-20',ARRAY['solidão','auxiliadora','animais','nomeação','comunhão'],genesis_two,18,20),
   ('b2000002-0000-4000-8000-000000000021',genesis_module,'genesis-2-21-25-mulher-e-uniao','Gênesis 2:21–25 — Mulher, aliança e união','Deus forma a mulher, estabelece a união de uma só carne e encerra a narrativa com transparência sem vergonha antes da queda.',65,'free',14,true,'published','Gênesis 2:21-25',ARRAY['mulher','casamento','uma só carne','nudez','aliança'],genesis_two,21,25)
  ON CONFLICT (module_id,slug) DO UPDATE SET title=EXCLUDED.title,summary=EXCLUDED.summary,duration_minutes=EXCLUDED.duration_minutes,order_index=EXCLUDED.order_index,is_published=true,status='published',passage=EXCLUDED.passage,keywords=EXCLUDED.keywords,chapter_id=EXCLUDED.chapter_id,verse_start=EXCLUDED.verse_start,verse_end=EXCLUDED.verse_end;

