CREATE TEMP TABLE genesis2_seed (lesson_id uuid, reference text, title text, objective text, overview text, observation text, immediate_context text, book_context text, historical text, cultural text, literary text, terms text, explanation text, theology text, interpretations text, not_saying text, cross_refs text, christ text, principles text, application text, meditation text, sermon text, outline_text text, errors text, challenge text, prayer text, reflection text, refs text[]) ON COMMIT DROP;

INSERT INTO genesis2_seed VALUES
('b2000002-0000-4000-8000-000000000001','Gênesis 2:1-3','O descanso de Deus','Ler a conclusão da criação atentando para obra concluída, bênção e santificação, sem projetar cansaço humano em Deus.','Depois de declarar a criação muito boa, a narrativa diz que céus e terra foram completados. Deus cessa sua obra no sétimo dia, abençoa-o e o separa para si. O texto dá dignidade ao tempo e aponta para a suficiência da obra criadora.','Marque a tríplice repetição de “sétimo dia” e de “obra”. Deus é o sujeito dos verbos terminou, descansou, abençoou e santificou. O descanso vem depois da obra completa; não é consequência de exaustão. A progressão é completar, cessar, abençoar e santificar.','Conclui Gênesis 1:1–2:3 e responde à avaliação “muito bom” de 1:31. Em 2:4 a narrativa recomeça com a fórmula das gerações e focaliza o ser humano. Dentro do capítulo, estabelece o padrão de Deus antes de apresentar trabalho humano no jardim.','Gênesis desenvolve bênção, santidade, trabalho e limites. O sétimo dia introduz um ritmo que a Lei de Israel posteriormente regulará, mas a passagem primeiro descreve a ação de Deus na criação.','FATO: o sétimo dia torna-se central no calendário e culto de Israel. INTERPRETAÇÃO: muitos leem aqui o fundamento do sábado. HIPÓTESE: não se pode provar, só por estes versículos, todos os detalhes de uma prática semanal humana anterior ao Sinai.','No antigo Oriente Próximo, descanso de uma divindade podia ser associado a habitar um templo depois de estabelecer ordem. A comparação pode iluminar a ideia de governo ordenado; não prova que Éden seja tecnicamente um templo nem reduz o texto a uma cópia cultural.','Prosa narrativa elevada encerra a primeira unidade por inclusio: criação “dos céus e da terra” (1:1; 2:1). A repetição do sétimo cria culminação, não um detalhe periférico.','Shabat, “cessar”, descreve interrupção da obra, não fadiga. Qiddesh, “santificou”, significa separar para um propósito. O verbo não obriga a imaginar que o dia tenha poder mágico.','O TEXTO DIZ que Deus termina e cessa sua obra, abençoa e santifica o sétimo dia. PODE-SE INFERIR que a criação tem ordem e limite. INTERPRETAÇÕES divergem sobre a relação direta com o sábado cristão. APLICAÇÃO: receber descanso e adoração como resposta ao Criador, não como mecanismo de mérito.','Deus é suficiente e soberano; criação, tempo, bênção e santidade pertencem a ele. O descanso não nega o valor do trabalho: ele o enquadra sob a obra terminada de Deus.','A tradição sabatista vê continuidade semanal forte; outras tradições distinguem sábado mosaico e princípio de descanso. Hebreus 4 aprofunda o tema em chave de fé e consumação. Essas leituras devem partir da criação sem confundir descrição e legislação posterior.','Não diz que Deus precisava recuperar forças, que toda folga humana é automaticamente santa, nem fornece calendário moderno completo. Também não autoriza preguiça ou legalismo.','AT: Êxodo 20:8-11 fundamenta o sábado na criação; Deuteronômio 5 acrescenta o êxodo; Salmos 95:7-11 relaciona descanso e fé. NT: Marcos 2:27-28 trata do sábado e do senhorio de Cristo; Hebreus 4:1-11 fala do descanso que permanece.','Conexão canônica: João 1:3 e Colossenses 1:16 incluem Cristo na obra criadora. Hebreus 4 apresenta Jesus como aquele que conduz seu povo ao descanso de Deus. Não há profecia direta de Cristo em cada ato do sétimo dia.','A obra de Deus é completa; tempo é dom sob seu governo; descanso santo orienta a criatura para confiança e adoração.','Vida pessoal: resistir à identidade baseada só em produtividade. Trabalho: trabalhar com limites e gratidão. Igreja: organizar descanso sem controlar consciências além da Escritura. Liderança: não usar o descanso como privilégio de poucos.','Que diferença existe entre descanso como dom e descanso como fuga? Onde trato produtividade como senhor? O que o texto afirma sobre Deus e o que eu apenas suponho?','TEXTO: Gênesis 2:1-3. TEMA: A obra completa e o descanso santo. IDEIA CENTRAL: Deus encerra sua obra boa e separa o tempo para que a criatura viva de sua suficiência. OBJETIVO: chamar à confiança adoradora. INTRODUÇÃO: nossa cultura nunca termina; Deus termina sua obra. PONTOS: obra completada; descanso divino; dia abençoado. APLICAÇÕES: adoração, limites e gratidão. CONCLUSÃO: em Cristo há descanso final.','Tema: “Descansar na obra completa de Deus”. 1) Deus completa sua obra (v.1): criação ordenada, fundamento de confiança. 2) Deus cessa sua obra (v.2): não por fraqueza, mas por plenitude. 3) Deus abençoa e santifica o dia (v.3): tempo recebido para Deus. Aplique contra ativismo e contra indolência.','Evite dizer que Deus se cansou, transformar a passagem em regra detalhada de calendário, ou prometer cura de esgotamento por uma única prática religiosa.','Escreva uma mensagem de três pontos cuja ideia central possa ser provada por cada versículo; depois avalie se suas aplicações distinguem criação, Lei mosaica e vida cristã.','Deus de toda a criação, ensina-nos a confiar em tua obra completa. Liberta-nos do ativismo orgulhoso e da preguiça que recusa tua vocação. Faz-nos descansar em Cristo com fé e gratidão. Amém.','O descanso bíblico não é vazio de propósito: é a criatura aprendendo que Deus continua sendo Deus quando ela deixa de produzir.',ARRAY['Gênesis 2:1-3','Êxodo 20:8-11','Deuteronômio 5:12-15','Marcos 2:27-28','Hebreus 4:1-11','Colossenses 1:16-17']),
('b2000002-0000-4000-8000-000000000004','Gênesis 2:4-7','O homem formado do pó','Observar a dependência humana diante do Senhor Deus e distinguir a linguagem narrativa das perguntas científicas que o texto não responde.','A nova seção focaliza a terra ainda sem cultivo, a provisão de água e a formação do humano do pó. Deus dá fôlego e o humano torna-se ser vivente: criatura material e vivificada por Deus.','Observe “Senhor Deus”, expressão repetida; terra/solo e humano têm som próximo no hebraico. Deus forma, sopra e faz crescer; o humano recebe vida. Não há autonomia humana.','Segue a semana concluída e antecede o jardim. Explica o cenário para a vocação de cultivar e guardar em 2:15 e prepara a tensão entre o pó e a morte em 3:19.','Gênesis conecta criação, solo, genealogia, morte e promessa. O humano vindo do solo mantém humildade diante do Criador, enquanto a vida recebida sustenta sua dignidade.','FATO: agricultura dependia de chuva, fontes e trabalho. INTERPRETAÇÃO: a névoa/fonte de v.6 é traduzida de modos diferentes. HIPÓTESE: identificar exatamente sua tecnologia hidráulica ou local vai além do texto.','O cultivo era fundamento econômico antigo; solo, água e vida eram experiências concretas. O relato rejeita autonomia: fertilidade e vida não são bens controlados pelo agricultor.','A fórmula “estas são as gerações” abre grande seção de Gênesis. O foco muda do panorama cósmico de Gênesis 1 para narrativa terrestre e humana, sem exigir dois criadores.','Adam pode designar humanidade ou homem; adamah, solo. Yatsar, “formar”, é imagem de artesão. Neshamah, fôlego, comunica vida recebida; não fornece uma anatomia completa da alma.','O TEXTO DIZ que o Senhor Deus forma do pó e dá fôlego de vida. PODE-SE INFERIR vulnerabilidade e dependência. INTERPRETAÇÃO: leituras sobre ordem cronológica com Gênesis 1 variam. APLICAÇÃO: dignidade e humildade caminham juntas.','Deus é doador de vida; humanidade é criatura corporal; trabalho e terra pertencem ao propósito original. A vida humana não é mero acidente nem divindade.','Alguns entendem 2 como recapitulação detalhada de 1; outros percebem ênfase literária distinta. A leitura mais natural do contexto trata o capítulo como foco complementar, não necessariamente cronologia independente.','Não diz que corpo seja mau, que homem tenha sido criado sem relação com a imagem de Deus de 1:26-27, nem explica cientificamente cada processo biológico.','AT: Gênesis 3:19 retoma pó e morte; Jó 33:4 atribui vida ao sopro de Deus; Salmos 103:14 lembra nossa fragilidade. NT: 1 Coríntios 15:45 contrasta Adão e Cristo; 2 Coríntios 4:7 aplica a imagem de vasos de barro.','Conexão canônica: 1 Coríntios 15:45 chama Adão de ser vivente e Cristo de espírito vivificante. É contraste apostólico entre o primeiro homem e o Cristo ressuscitado, não alegoria do pó.','Vida é recebida; corpo e terra importam; dependência do Criador humilha sem desumanizar.','Caráter: cultivar humildade. Família e igreja: honrar corpos frágeis e pessoas idosas. Trabalho: cuidar da terra sem idolatrá-la. Pregação: não usar o pó para diminuir a dignidade humana.','Como posso afirmar simultaneamente fragilidade e dignidade? Que detalhes do texto me impedem de tratar vida como propriedade minha?','TEXTO: Gênesis 2:4-7. TEMA: Vida recebida do Criador. IDEIA CENTRAL: o humano é criatura do solo, vivificada pelo sopro de Deus e chamada a depender dele. OBJETIVO: formar humildade reverente. PONTOS: cenário sem cultivo; Deus forma; Deus dá vida.','Tema: “Pó nas mãos de Deus”. 1) O cenário revela dependência (vv.4-6). 2) Deus forma o humano (v.7a). 3) Deus concede vida (v.7b). Aplicação: reverência pelo corpo, humildade e cuidado do próximo.','Evite opor Gênesis 1 a 2, reduzir pessoa a matéria, construir doutrina completa da alma apenas com “fôlego”, ou usar o pó para justificar desprezo.','Liste os verbos de Deus e os elementos recebidos pelo humano. Formule uma aplicação que honre tanto a vulnerabilidade corporal quanto a dignidade humana.','Senhor Deus, reconhecemos que nossa vida vem de ti. Ensina-nos humildade sem desespero e cuidado pelo corpo sem idolatria. Sustenta-nos pelo teu dom e forma em nós caráter fiel. Amém.','Quem recebeu o fôlego não pode viver como dono absoluto de si mesmo; vive com gratidão diante do Doador.',ARRAY['Gênesis 2:4-7','Gênesis 3:19','Jó 33:4','Salmos 103:14','1 Coríntios 15:45-49','2 Coríntios 4:7']),
('b2000002-0000-4000-8000-000000000008','Gênesis 2:8-14','O jardim do Éden','Aprender a observar provisão, vida e limites geográficos sem alegorizar o jardim ou fingir certeza onde a localização é desconhecida.','O Senhor Deus planta um jardim e nele coloca o humano. Árvores belas e boas para alimento, a árvore da vida e a árvore do conhecimento são nomeadas; um rio se divide em quatro. O quadro comunica provisão abundante e cenário preparado por Deus.','Identifique os verbos: Deus planta, faz brotar e coloca. Repare em beleza e alimento juntos, duas árvores destacadas e movimento do rio para fora. Os nomes dos rios criam sensação de lugar, mas nem todos são localizáveis hoje.','Segue a formação do humano e prepara a colocação, trabalho e mandamento de 2:15-17. O jardim é dom antes de se tornar lugar de prova.','Terra, bênção, rios e árvores atravessam Gênesis e culminam em visão de vida restaurada. O livro apresenta o mundo como lugar de provisão de Deus, depois ferido pelo pecado.','FATO: Tigre e Eufrates são rios conhecidos da Mesopotâmia. INTERPRETAÇÃO: alguns localizam o Éden naquela região. INCERTEZA: Pison e Giom, e portanto o local exato, não são identificáveis com segurança.','Jardins reais eram símbolos de abundância em regiões de cultivo árido. Metais e pedras preciosas indicam riqueza; o texto não autoriza prosperidade individual automática.','A narrativa alterna visão ampla e detalhes: plantio, árvores, rio e seus braços. O jardim antecede a proibição: generosidade molda a leitura do limite.','Gan é jardim; eden provavelmente comunica deleite, embora o nome também funcione como local. Etz ha-chayyim é árvore da vida; sua função plena será desenvolvida canonicamente, não definida apenas por etimologia.','O TEXTO DIZ que Deus provê um lugar bom, alimento e árvores específicas. PODE-SE INFERIR cuidado e abundância. INTERPRETAÇÃO: o jardim como santuário é proposta plausível por paralelos literários, mas não declaração explícita. APLICAÇÃO: gratidão e responsabilidade.','Deus provê antes de ordenar; vida pertence a ele; bondade material é afirmada. O futuro acesso à árvore da vida torna a rebelião de Gênesis 3 especialmente séria.','Há leituras de geografia histórica, simbólica ou ambas. Não há consenso sobre localização. A presença de rios conhecidos não remove as dificuldades de identificação.','Não diz que possuímos hoje o mapa do Éden, que todo detalhe mineral simboliza uma realidade espiritual, ou que riqueza é sinal garantido de aprovação divina.','AT: Ezequiel 28:13 usa Éden em linguagem profética; Ezequiel 47:1-12 retrata rio de vida. NT: Apocalipse 2:7 e 22:1-2 retomam árvore e rio de vida.','Conexão canônica: Apocalipse retoma árvore e rio para descrever a vida restaurada pelo Cordeiro. É desenvolvimento temático, não licença para transformar cada rio em símbolo de Cristo.','Deus é generoso; provisão e beleza são boas; vida verdadeira depende de Deus; dons devem ser recebidos como mordomia.','Vida pessoal: praticar gratidão. Trabalho e criação: cuidar do que Deus provê. Igreja: evitar evangelho de prosperidade. Liderança: oferecer recursos como serviço, não controle.','Que provisões eu trato como direitos? Onde a beleza criada me conduz ao Criador, e onde me conduz ao consumo?','TEXTO: Gênesis 2:8-14. TEMA: O Deus que provê vida. IDEIA CENTRAL: Deus prepara generosamente um lugar de vida para sua criatura, que deve recebê-lo como dom. OBJETIVO: formar gratidão responsável. PONTOS: Deus planta; Deus faz crescer; Deus faz fluir.','Tema: “O dom antes da demanda”. 1) Deus prepara o jardim (v.8). 2) Deus concede beleza e alimento (v.9). 3) Deus faz a vida transbordar (vv.10-14). Aplique gratidão, cuidado e sobriedade.','Evite localizar o Éden com certeza, alegorizar ouro e rios, ou confundir abundância criada com promessa universal de riqueza.','Faça uma tabela: dados geográficos certos, dados incertos e inferências teológicas. Depois pregue a generosidade de Deus sem prometer bens materiais aos ouvintes.','Deus generoso, abre nossos olhos para teus dons. Livra-nos de transformar provisão em ídolo e ensina-nos a cuidar com gratidão do que colocas em nossas mãos. Amém.','O jardim ensina que a vida começa com generosidade divina; a resposta fiel não é posse, mas gratidão obediente.',ARRAY['Gênesis 2:8-14','Ezequiel 47:1-12','Ezequiel 28:13','Apocalipse 2:7','Apocalipse 22:1-2','Apocalipse 22:14']),
('b2000002-0000-4000-8000-000000000015','Gênesis 2:15-17','Trabalho, limite e mandamento','Interpretar trabalho e mandamento como dádivas sob a autoridade de Deus, observando cuidadosamente liberdade, proibição e consequência.','Deus coloca o humano no jardim para cultivar e guardar. A permissão é ampla; uma única árvore é proibida, com consequência anunciada. Liberdade humana existe dentro da bondade e autoridade do Criador.','Sublinhe colocou, cultivar, guardar, ordenar, comer, não comer e morrer. O contraste é “de toda árvore” e “mas desta”. A ordem vem antes da queda e a consequência é declarada, não escondida.','Segue a provisão do jardim e antecede a formação da mulher. Prepara diretamente a tentação de 3:1-6, onde a palavra de Deus será questionada e distorcida.','Gênesis mostra que pecado não nasce da escassez, mas da desconfiança e transgressão. Trabalho, solo, morte e exílio reaparecerão após a queda.','FATO: campos e jardins exigiam proteção e cultivo. INTERPRETAÇÃO: os verbos são usados depois para serviço e guarda ligados ao santuário. INFERÊNCIA CAUTELOSA: isso pode enriquecer a vocação de Adão, sem provar sozinho que o jardim era templo.','Mandamentos antigos estabeleciam lealdade e limites de vida comunitária. Aqui o mandamento é dado pelo Deus que já proveu amplamente; não é capricho em meio à falta.','A estrutura permission-prohibition-consequence põe a ênfase na generosidade antes da restrição. A repetição de “árvore” liga a unidade à cena seguinte.','Avad pode significar servir/cultivar; shamar, guardar/proteger. Mot tamut é construção intensiva, “certamente morrerás”; a forma enfatiza certeza, mas o modo preciso da morte se desenvolve na narrativa.','O TEXTO DIZ que Deus dá tarefa, ampla permissão e limite real. PODE-SE INFERIR que obediência é relacional e responsável. INTERPRETAÇÃO debate a relação entre morte imediata, processo mortal e separação de Deus. APLICAÇÃO: obedecer ao Deus generoso.','Trabalho antecede pecado; autoridade de Deus é boa; obediência possui consequências; liberdade criada não é autonomia moral absoluta.','Alguns entendem “no dia” como morte física naquele dia; outros, início da condição mortal e ruptura relacional. Gênesis 3 mostra alienação, sentença e retorno ao pó, portanto a explicação deve manter juntas as dimensões narrativas.','Não diz que todo trabalho é maldição, que toda dificuldade profissional é punição pessoal, nem que a árvore era má. Não autoriza líderes a inventarem limites com a mesma autoridade de Deus.','AT: Deuteronômio 30:15-20 coloca vida e morte diante de Israel; Salmos 19:7-11 celebra a bondade da instrução. NT: Romanos 5:12-19 liga Adão e morte; 1 Coríntios 15:21-22 contrasta morte e ressurreição.','Conexão canônica: Cristo obedece onde Adão falha e, por sua obediência, traz vida (Romanos 5:18-19). É contraste apostólico, não identificação da árvore como cruz.','Trabalho é vocação; obediência nasce da confiança; limites podem proteger vida; consequências morais são sérias.','Vida pessoal: examinar desconfiança por trás da desobediência. Trabalho: servir e guardar com integridade. Liderança: usar autoridade para proteger, sem usurpar a voz divina. Igreja: ensinar graça que não banaliza obediência.','Que generosidade de Deus antecede seus limites? Em que área chamo autonomia de liberdade? Como aplicarei o texto sem criar regras humanas absolutas?','TEXTO: Gênesis 2:15-17. TEMA: Liberdade sob a palavra de Deus. IDEIA CENTRAL: o Criador confia uma vocação generosa e um limite claro, chamando sua criatura à obediência que conduz à vida. OBJETIVO: formar confiança obediente. PONTOS: colocado para servir; ampla permissão; limite e consequência.','Tema: “A boa liberdade que ouve Deus”. 1) Vocação no jardim (v.15). 2) Generosidade da permissão (v.16). 3) Seriedade do limite (v.17). Aplicação: integridade, discernimento e confiança no evangelho.','Evite chamar trabalho de maldição, confundir limite divino com preferência pessoal, ou resolver simplistamente toda a questão da morte em uma frase.','Escreva uma aplicação para trabalhador, líder e jovem; em cada uma, mostre como a graça de Deus evita tanto legalismo quanto autonomia.','Senhor, dá-nos alegria em servir e coragem para guardar tua palavra. Perdoa nossa suspeita diante de teus limites e forma em nós a obediência que confia em tua bondade. Por Cristo, amém.','A obediência não compra o jardim; ela responde ao Deus que já colocou sua criatura nele e lhe falou com clareza.',ARRAY['Gênesis 2:15-17','Gênesis 3:1-6','Deuteronômio 30:15-20','Salmos 19:7-11','Romanos 5:12-19','1 Coríntios 15:21-22']),
('b2000002-0000-4000-8000-000000000018','Gênesis 2:18-20','Não é bom que o homem esteja só','Reconhecer a bondade da comunhão humana e ler “auxiliadora correspondente” sem diminuir a mulher nem transferir a função dos animais para o casamento.','Deus declara que a solidão do homem não é boa e anuncia uma auxiliadora que lhe corresponda. Os animais são trazidos e nomeados, mas nenhum corresponde ao humano. A narrativa cria expectativa para a mulher.','Observe a primeira expressão “não é bom”, em contraste com o “bom” de Gênesis 1. Deus fala, forma/traz animais, o homem nomeia, e a falta permanece. “Para ele” fecha a busca.','Segue o mandamento e antecede a formação da mulher. A nomeação dos animais não resolve a solidão; sua função literária é mostrar que a parceira humana não é encontrada entre eles.','Gênesis apresenta humanidade criada homem e mulher (1:27) e agora descreve a formação da comunidade humana. Famílias, descendência e alianças ocuparão o restante do livro.','FATO: nomes podem reconhecer e distinguir criaturas. INTERPRETAÇÃO: nomear sugere responsabilidade humana. HIPÓTESE: não é possível reconstruir uma taxonomia antiga completa a partir desta cena.','Auxílio não denota inferioridade: o mesmo termo pode descrever o auxílio de Deus a seu povo. Correspondência comunica adequação frente a frente, não identidade sem diferença.','A cena usa demora narrativa: anúncio, animais, ausência de par e resolução nos vv.21-25. É uma unidade preparada pela repetição de “para o homem”.','Ezer é auxílio; em outros textos frequentemente Deus é o auxiliador. Kenegdo traz ideia de “correspondente a ele”, adequada diante dele. Os termos não definem todos os papéis familiares posteriores isoladamente.','O TEXTO DIZ que a solidão é não boa e nenhum animal é par correspondente. PODE-SE INFERIR que pessoas necessitam de comunhão humana. INTERPRETAÇÃO: aplicação ao casamento deve respeitar que nem toda pessoa é chamada a casar.','Deus vê a necessidade humana; homem e mulher possuem dignidade comum; criaturas têm valor, mas não substituem comunhão humana; responsabilidade acompanha autoridade.','Alguns destacam complementaridade de homem e mulher; outros enfatizam mutualidade. O próprio texto sustenta ambos: diferença corporal narrada e ajuda correspondente, não subserviente.','Não diz que solteiros são defeituosos, que animais não importam, que a mulher foi criada para ser serva, ou que toda amizade é substituto de casamento.','AT: Salmos 121:1-2 usa auxílio de Deus; Provérbios 18:22 celebra esposa sem legislar cada caso. NT: Mateus 19:4-6 retoma criação; 1 Coríntios 7 honra também a vocação de solteiro.','Conexão canônica: Cristo acolhe e forma uma comunidade de discípulos; o NT retoma criação para casamento e também honra celibato para o reino. Não é profecia direta nesta unidade.','Ninguém foi criado para isolamento absoluto; auxílio é honra, não inferioridade; autoridade sobre criaturas requer responsabilidade; comunhão não é uniformidade.','Família: cultivar ajuda mútua. Igreja: incluir solteiros, viúvos e pessoas isoladas. Liderança: rejeitar misoginia e autoritarismo. Vida pessoal: buscar comunhão sem fazer de outra pessoa um salvador.','Como trato pessoas solteiras em minha igreja? Que palavra no texto impede que “auxílio” signifique inferioridade? Onde preciso receber ou oferecer ajuda?','TEXTO: Gênesis 2:18-20. TEMA: A boa comunhão diante de Deus. IDEIA CENTRAL: Deus identifica a solidão humana e prepara uma parceira correspondente, sem confundir criatura animal e comunhão humana. OBJETIVO: formar comunidades de honra. PONTOS: Deus vê; o homem nomeia; nenhuma criatura corresponde.','Tema: “Não é bom estar só”. 1) Deus nomeia a necessidade (v.18). 2) O humano exerce responsabilidade sobre animais (vv.19-20a). 3) A insuficiência prepara a comunhão correspondente (v.20b). Aplique cuidado, inclusão e honra.','Evite chamar solteirice de fracasso, reduzir ezer a assistente inferior, ou fazer dos animais o foco principal da passagem.','Prepare um esboço que aplique o texto a uma igreja com casados e solteiros. Revise cada ponto para não transformar casamento em ídolo nem inferiorizar a mulher.','Deus de comunhão, livra-nos do isolamento e do orgulho. Ensina-nos a honrar homens e mulheres, acolher os sós e oferecer ajuda que reflita teu cuidado. Amém.','A primeira coisa “não boa” não é a matéria ou o trabalho, mas a solidão humana; Deus responde com comunhão digna.',ARRAY['Gênesis 2:18-20','Salmos 121:1-2','Provérbios 18:22','Mateus 19:4-6','1 Coríntios 7:6-9','1 Coríntios 12:12-27']),
('b2000002-0000-4000-8000-000000000021','Gênesis 2:21-25','Mulher, aliança e união','Expor a formação da mulher e a união de uma só carne com fidelidade ao texto, aplicando casamento com honra e sem silenciar a vocação de solteiros.','Deus faz a mulher a partir do lado do homem e a traz a ele. O homem responde em poesia de reconhecimento; o narrador estabelece deixar, unir-se e tornar-se uma só carne. Nudez sem vergonha encerra a criação antes da ruptura de Gênesis 3.','Observe a iniciativa divina: faz cair sono, toma, forma e traz. A fala do homem é poema e inclui “osso” e “carne”; depois o narrador universaliza com “por isso”. O contraste final com 3:7 é nudez sem vergonha/consciência de vergonha.','Resolve a falta de 2:18-20 e prepara a queda, que atingirá unidade, confiança e corpo. O capítulo termina em comunhão com Deus, terra e outro ser humano.','Casamento, famílias, conflitos e promessa de descendência percorrem Gênesis. Esta passagem fornece uma visão de origem que Jesus usa ao ensinar sobre casamento.','FATO: casamento no antigo mundo envolvia deixar a casa de origem e formar nova unidade doméstica. INTERPRETAÇÃO: “lado” em vez de “costela” destaca proximidade, mas o texto não constrói uma hierarquia anatômica.','“Uma só carne” aponta para união de parentesco, corpo e vida compartilhada; inclui sexualidade, mas é mais ampla que ato sexual isolado. Vergonha aqui não é mera ausência de roupa, mas ausência de ruptura e medo.','A unidade alterna ação de Deus, poema humano e comentário narrativo. O poema marca reconhecimento jubiloso; o comentário aplica o padrão além do primeiro casal.','Tsela normalmente significa lado/lateral, embora traduções tradicionais usem costela. Ish/ishah jogam com homem/mulher na fala; o argumento do texto é relação, não uma etimologia científica. Davaq, apegar-se, expressa adesão firme.','O TEXTO DIZ que Deus forma e traz a mulher, e que homem e mulher tornam-se uma só carne. PODE-SE INFERIR exclusividade e nova lealdade. INTERPRETAÇÕES discutem detalhes de papéis conjugais; APLICAÇÃO deve promover fidelidade, dignidade e proteção.','Deus cria comunhão sexual e pactual; casamento é dádiva, unidade e nova lealdade; corpo é bom; vergonha surge depois da queda, não da criação.','Cristãos divergem sobre como textos posteriores descrevem responsabilidades conjugais. Gênesis 2 insiste na correspondência e unidade. Mateus 19 usa a passagem para a união matrimonial; 1 Coríntios 7 mantém também a dignidade da solteirice.','Não diz que mulher é inferior ou propriedade do homem, que todo adulto deve casar, que casamento elimina todo conflito, ou que nudez sem vergonha justifica exposição pública sem limites.','AT: Malaquias 2:14 fala da aliança conjugal; Provérbios 2:17 usa linguagem de aliança. NT: Mateus 19:4-6 cita Gênesis; Efésios 5:31-32 cita uma só carne; Apocalipse 19:6-9 usa bodas como imagem escatológica.','Citação do NT: Jesus cita Gênesis 1:27 e 2:24 ao ensinar sobre casamento. Efésios 5 chama a união matrimonial de mistério ligado a Cristo e à igreja; trata-se de conexão tipológica/canônica, não de alegoria de cada detalhe da formação da mulher.','Homem e mulher compartilham humanidade; casamento requer aliança e lealdade; intimidade floresce em segurança e verdade; Deus é autor do dom, não o casal autônomo.','Casamento: cultivar fidelidade e serviço mútuo. Família: apoiar novos lares sem isolá-los. Igreja: proteger vulneráveis e honrar solteiros. Liderança: jamais usar o texto para justificar abuso. Caráter: trocar vergonha escondida por verdade e graça em Cristo.','Como a nova lealdade do casamento corrige interferências indevidas? Como igreja pode celebrar casamento sem tratar solteiros como incompletos? Onde a vergonha precisa encontrar a graça de Cristo?','TEXTO: Gênesis 2:21-25. TEMA: Unidade recebida de Deus. IDEIA CENTRAL: Deus forma a mulher e estabelece uma união de aliança, corporal e fiel, marcada por confiança antes da queda. OBJETIVO: chamar à honra e fidelidade. INTRODUÇÃO: a cultura trata vínculo como consumo; o Criador o chama de união. PONTOS: Deus forma e traz; o homem reconhece; o narrador estabelece a união.','Tema: “Uma só carne, uma fidelidade”. 1) Deus age pela comunhão (vv.21-22). 2) O homem recebe a mulher com reconhecimento (v.23). 3) Deus estabelece nova união (v.24) e confiança sem vergonha (v.25). Aplicação: aliança, cuidado e graça para feridas reais.','Evite usar “costela” para superioridade masculina, aplicar casamento como exigência a todos, prometer perfeição conjugal, ou ler Efésios 5 de modo que apague o sentido primeiro de Gênesis.','Antes do exemplo, faça esboço para uma congregação diversa. Inclua uma aplicação para casados, uma para solteiros e uma salvaguarda explícita contra abuso espiritual.','Criador fiel, obrigado pelo dom da comunhão e pelo cuidado que desejas para nossos lares. Cura relações feridas, forma em nós fidelidade e protege os vulneráveis. Faz tua igreja refletir a graça de Cristo. Amém.','No princípio, a intimidade não era posse nem medo: era comunhão recebida de Deus. O evangelho chama os feridos a caminhar para essa verdade com fidelidade e graça.',ARRAY['Gênesis 2:21-25','Malaquias 2:14','Provérbios 2:17','Mateus 19:4-6','1 Coríntios 7:6-9','Efésios 5:31-32','Apocalipse 19:6-9']);

INSERT INTO public.lesson_content (lesson_id,kind,title,body,scripture_refs,order_index)
SELECT s.lesson_id,v.kind,v.title,v.body,CASE WHEN v.refs THEN s.refs ELSE ARRAY[s.reference] END,v.ord
FROM genesis2_seed s CROSS JOIN LATERAL (VALUES
 (1,'referencias','1. Referência bíblica',s.reference,true),(2,'introducao','2. Título da passagem',s.title,false),(3,'objetivos','3. Objetivo da aula',s.objective,false),(4,'texto','4. Visão geral',s.overview,false),(5,'observacao','5. Observação detalhada do texto',s.observation,false),(6,'contexto','6. Contexto imediato',s.immediate_context,false),(7,'contexto','7. Contexto do livro',s.book_context,false),(8,'contexto','8. Contexto histórico',s.historical,false),(9,'contexto_cultural','9. Contexto cultural',s.cultural,false),(10,'interpretacao','10. Contexto literário',s.literary,false),(11,'glossario','11. Termos hebraicos relevantes',s.terms,false),(12,'interpretacao','12. Explicação aprofundada',s.explanation,true),(13,'principios','13. Questões teológicas',s.theology,false),(14,'interpretacao','14. Questões interpretativas',s.interpretations,false),(15,'interpretacao','15. O que o texto não diz',s.not_saying,false),(16,'referencias_cruzadas','16. Referências cruzadas',s.cross_refs,true),(17,'conexao_cristo','17. Relação com Cristo',s.christ,true),(18,'principios','18. Princípios bíblicos',s.principles,false),(19,'aplicacao','19. Aplicação',s.application,false),(20,'meditacao','20. Meditação',s.meditation,false),(21,'meditacao','21. Meditação do aluno','Use o Caderno do pregador e responda: “O que Deus me ensinou através deste estudo?” Seu registro é privado e pode ser atualizado.',false),(22,'exercicio','22. Teste de entendimento','Responda às perguntas de compreensão abaixo; elas avaliam leitura, contexto e interpretação, não só memória.',false),(23,'exercicio','23. Exercício de observação e interpretação','No Caderno do pregador, registre ideia central, observações, palavras-chave, contexto, princípio e aplicação. Em seguida explique: “O que esta passagem realmente está ensinando?”',false),(24,'pregacao','24. Preparando a mensagem',s.sermon,true),(25,'pregacao','25. Exemplo de esboço',s.outline_text,true),(26,'interpretacao','26. Erros de interpretação a evitar',s.errors,false),(27,'desafio','27. Desafio do pregador',s.challenge,false),(28,'oracao','28. Oração',s.prayer,false),(29,'encerramento','29. Reflexão final',s.reflection,false)
) v(ord,kind,title,body,refs);

INSERT INTO public.lesson_questions (lesson_id,kind,prompt,options,answer_key,explanation,scripture_refs,order_index)
SELECT s.lesson_id,'reflexao',q.prompt,'[]'::jsonb,NULL,q.explanation,s.refs,q.ord FROM genesis2_seed s CROSS JOIN LATERAL (VALUES
 (1,'Qual é a ideia central desta passagem sem acrescentar suposições externas?',s.objective),(2,'Quais verbos, repetições, contrastes ou progressões sustentam sua resposta?',s.observation),(3,'Qual é o limite interpretativo mais importante a preservar nesta aula?',s.not_saying),(4,'Como a conexão com Cristo respeita o sentido primeiro da passagem?',s.christ)
) q(ord,prompt,explanation);

INSERT INTO public.lesson_exercises (lesson_id,kind,title,instructions,fields,order_index,status)
SELECT lesson_id,'observacao','Exercício de observação e interpretação','Comece pela passagem. Registre evidências antes de interpretar e só então formule aplicações responsáveis.',jsonb_build_array(jsonb_build_object('key','ideia_central','label','Ideia central','placeholder','Uma frase sustentada pelo texto.'),jsonb_build_object('key','observacoes','label','Observações e palavras-chave','placeholder','Verbos, repetições, contrastes e estrutura.'),jsonb_build_object('key','contexto','label','Contexto','placeholder','O que vem antes, depois e no livro?'),jsonb_build_object('key','principio','label','Princípio bíblico','placeholder','Verdade que atravessa contextos.'),jsonb_build_object('key','interpretacao','label','O que a passagem realmente ensina?','placeholder','Explique sem alegorizar ou ultrapassar o texto.'),jsonb_build_object('key','aplicacao','label','Aplicação responsável','placeholder','Como responder hoje sem transformar descrição em promessa.')),1,'published'::public.content_status FROM genesis2_seed
UNION ALL SELECT lesson_id,'pregacao','Prepare sua própria mensagem','Prepare um esboço antes de reler o exemplo. TEXTO, TEMA, IDEIA CENTRAL, OBJETIVO, INTRODUÇÃO, três pontos, aplicações e conclusão devem nascer da passagem.',jsonb_build_array(jsonb_build_object('key','tema','label','Tema','placeholder','Título fiel ao texto.'),jsonb_build_object('key','ideia_central','label','Ideia central','placeholder','Verdade central em uma frase.'),jsonb_build_object('key','objetivo','label','Objetivo','placeholder','Resposta esperada dos ouvintes.'),jsonb_build_object('key','introducao','label','Introdução','placeholder','Conduza ao problema do texto.'),jsonb_build_object('key','pontos','label','Pontos e fundamento bíblico','placeholder','Até três pontos extraídos dos versículos.'),jsonb_build_object('key','aplicacoes','label','Aplicações','placeholder','Aplicações específicas, responsáveis e pastorais.'),jsonb_build_object('key','conclusao','label','Conclusão','placeholder','Retome a ideia central e a resposta esperada.')),2,'published'::public.content_status FROM genesis2_seed;

INSERT INTO public.lesson_cross_references (lesson_id,reference,relation_kind,explanation,order_index)
SELECT s.lesson_id,r.ref,CASE WHEN r.ref ~ '^(Mateus|Marcos|João|Romanos|1 Coríntios|2 Coríntios|Efésios|Colossenses|Hebreus|Apocalipse)' THEN 'novo_testamento' ELSE 'antigo_testamento' END,'Referência canônica selecionada por relação textual ou temática direta; a explicação específica está na seção de referências cruzadas.',r.ord FROM genesis2_seed s CROSS JOIN LATERAL unnest(s.refs) WITH ORDINALITY r(ref,ord) WHERE r.ref<>s.reference;

INSERT INTO public.content_sources (lesson_id,kind,title,author,detail,url,order_index)
SELECT lesson_id,'texto_biblico','Texto hebraico de Gênesis 2','Bíblia Hebraica','Referência ao texto massorético para vocabulário e estrutura; nenhuma tradução moderna protegida foi reproduzida.',NULL,1 FROM genesis2_seed
UNION ALL SELECT lesson_id,'lexico','Léxico do Antigo Testamento','Brown, Driver e Briggs','Consulta lexical contextual; nenhum argumento doutrinário depende de etimologia isolada.','https://archive.org/details/hebrewenglishlex00browuoft',2 FROM genesis2_seed
UNION ALL SELECT lesson_id,'historico','Contexto do antigo Oriente Próximo','Síntese editorial original','Contextos comparativos foram apresentados com distinção explícita entre fato, interpretação, hipótese e incerteza.',NULL,3 FROM genesis2_seed
UNION ALL SELECT lesson_id,'biblico','Referências canônicas','Caminhando com Cristo','Seleção original de passagens bíblicas relacionadas, explicada no estudo.',NULL,4 FROM genesis2_seed;
